CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE "AppContentState" AS ENUM ('DRAFT','PUBLISHED');
CREATE TYPE "AppAvailability" AS ENUM ('AVAILABLE','COMING_SOON','DISCONTINUED');
CREATE TYPE "ReleaseState" AS ENUM ('DRAFT','PUBLISHED');
CREATE TYPE "MessageKind" AS ENUM ('GENERAL','SUPPORT');
CREATE TYPE "MessageStatus" AS ENUM ('NEW','READ','REPLIED','ARCHIVED');
CREATE TYPE "ArticleState" AS ENUM ('DRAFT','PUBLISHED');
CREATE TYPE "MediaRole" AS ENUM ('ICON','COVER','SCREENSHOT','OG');
CREATE TYPE "ReleaseChangeKind" AS ENUM ('ADDED','IMPROVED','FIXED','REMOVED','SECURITY');
CREATE TABLE roles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,permissions jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),email text UNIQUE NOT NULL,password_hash text NOT NULL,name text NOT NULL,role_id uuid NOT NULL REFERENCES roles(id) ON DELETE RESTRICT,active boolean NOT NULL DEFAULT true,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE admin_sessions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES admin_users(id) ON DELETE CASCADE,token_hash text UNIQUE NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX admin_sessions_expiry_idx ON admin_sessions(expires_at);
CREATE TABLE categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,slug text UNIQUE NOT NULL,sort_order int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE platforms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text UNIQUE NOT NULL,slug text UNIQUE NOT NULL,sort_order int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE applications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,slug text UNIQUE NOT NULL,tagline text NOT NULL DEFAULT '',short_description text NOT NULL DEFAULT '',description text NOT NULL DEFAULT '',category_id uuid REFERENCES categories(id) ON DELETE SET NULL,pricing_label text,bundle_id text,featured boolean NOT NULL DEFAULT false,display_order int NOT NULL DEFAULT 0,content_state "AppContentState" NOT NULL DEFAULT 'DRAFT',availability "AppAvailability" NOT NULL DEFAULT 'AVAILABLE',seo_title text,seo_description text,icon_url text,cover_url text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX applications_listing_idx ON applications(content_state,availability,featured,display_order);
CREATE TABLE application_platforms(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE,platform_id uuid NOT NULL REFERENCES platforms(id) ON DELETE RESTRICT,url text,label text,UNIQUE(application_id,platform_id));
CREATE TABLE application_features(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE,title text NOT NULL,body text NOT NULL DEFAULT '',sort_order int NOT NULL DEFAULT 0);CREATE INDEX application_features_order_idx ON application_features(application_id,sort_order);
CREATE TABLE media_assets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),storage_key text UNIQUE NOT NULL,original_filename text NOT NULL,stored_name text NOT NULL,mime_type text NOT NULL,size int NOT NULL CHECK(size>=0),width int,height int,alt_text text NOT NULL DEFAULT '',uploaded_by uuid REFERENCES admin_users(id) ON DELETE SET NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE application_media(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE,asset_id uuid NOT NULL REFERENCES media_assets(id) ON DELETE RESTRICT,role "MediaRole" NOT NULL,sort_order int NOT NULL DEFAULT 0,UNIQUE(application_id,asset_id,role));
CREATE TABLE releases(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),application_id uuid NOT NULL REFERENCES applications(id) ON DELETE CASCADE,version text NOT NULL,title text NOT NULL,description text NOT NULL DEFAULT '',release_date timestamptz NOT NULL DEFAULT now(),status "ReleaseState" NOT NULL DEFAULT 'DRAFT',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(application_id,version));CREATE INDEX releases_public_idx ON releases(application_id,status,release_date DESC);
CREATE TABLE release_changes(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),release_id uuid NOT NULL REFERENCES releases(id) ON DELETE CASCADE,kind "ReleaseChangeKind" NOT NULL,text text NOT NULL,sort_order int NOT NULL DEFAULT 0);
CREATE TABLE pages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),slug text UNIQUE NOT NULL,title text NOT NULL,content jsonb NOT NULL DEFAULT '{}',published boolean NOT NULL DEFAULT true,seo_title text,seo_description text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE page_sections(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),page_id uuid NOT NULL REFERENCES pages(id) ON DELETE CASCADE,kind text NOT NULL,data jsonb NOT NULL,visible boolean NOT NULL DEFAULT true,sort_order int NOT NULL DEFAULT 0);
CREATE TABLE legal_documents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,slug text UNIQUE NOT NULL,type text NOT NULL,content text NOT NULL,effective_date timestamptz,updated_date timestamptz,status "ArticleState" NOT NULL DEFAULT 'DRAFT',application_id uuid REFERENCES applications(id) ON DELETE CASCADE,seo_title text,seo_description text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_categories(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,slug text UNIQUE NOT NULL,description text NOT NULL DEFAULT '',sort_order int NOT NULL DEFAULT 0);
CREATE TABLE faqs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),question text NOT NULL,answer text NOT NULL,category_id uuid REFERENCES support_categories(id) ON DELETE SET NULL,application_id uuid REFERENCES applications(id) ON DELETE CASCADE,status "ArticleState" NOT NULL DEFAULT 'DRAFT',sort_order int NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE help_articles(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),title text NOT NULL,slug text UNIQUE NOT NULL,excerpt text NOT NULL DEFAULT '',content text NOT NULL,category_id uuid REFERENCES support_categories(id) ON DELETE SET NULL,application_id uuid REFERENCES applications(id) ON DELETE CASCADE,status "ArticleState" NOT NULL DEFAULT 'DRAFT',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE contact_messages(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL,subject text NOT NULL,message text NOT NULL,kind "MessageKind" NOT NULL DEFAULT 'GENERAL',status "MessageStatus" NOT NULL DEFAULT 'NEW',application_id uuid REFERENCES applications(id) ON DELETE SET NULL,abuse_hash text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());CREATE INDEX contact_messages_status_idx ON contact_messages(status,created_at DESC);
CREATE TABLE site_settings(key text PRIMARY KEY,value jsonb NOT NULL,updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE navigation_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),label text NOT NULL,href text NOT NULL,"group" text NOT NULL CHECK("group" IN ('header','footer')),sort_order int NOT NULL DEFAULT 0,visible boolean NOT NULL DEFAULT true);CREATE INDEX navigation_order_idx ON navigation_items("group",visible,sort_order);
CREATE TABLE analytics_events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event text NOT NULL,path text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX analytics_events_created_idx ON analytics_events(created_at,event);
CREATE TABLE audit_logs(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor_id uuid REFERENCES admin_users(id) ON DELETE SET NULL,action text NOT NULL,entity text NOT NULL,entity_id text,summary jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX audit_logs_created_idx ON audit_logs(created_at DESC);
